prompt:
You are optimizing a C function for speed.

Write a single C source file that defines

    void matmul(const float *A, const float *B, float *C, int n);

which computes C = A * B for square n x n matrices of single-precision (float) values stored in row-major order, so element (i, j) of A is A[i*n + j]. The three buffers do not overlap. C is not initialized: your function must write every element of C.

Requirements:
- The result must be correct for every positive n, not only for convenient sizes. Results are checked against a reference with a relative tolerance of about 1e-3, so reordering floating-point sums is fine.
- The benchmark runs large matrices (around a thousand rows and columns) and reports the best of several runs, so optimize for large n.
- The file is compiled with gcc and linked, together with a fixed benchmark harness that calls matmul, against the C math library and pthreads. Do not define main. Only the C standard library, libm, pthreads and OpenMP are available.
- You choose the compiler flags. They are passed to gcc as given (for example -O3 or -fopenmp). Flags that set the output file, add include or library paths, or pass options through to the linker are rejected.
- The program is built and run inside a Linux container, not on the machine you are running on. The CPU is not disclosed.
- Optimize for speed on the machine this runs on.

Reply format. Reply with the complete source file in exactly one fenced block:

```c
...
```

followed on its own line by the compiler flags, for example:

FLAGS: -O3 -march=native

Do not write any other code block or any other line starting with FLAGS:.

Below are your attempts so far, oldest first. Each was compiled and run; the observations are measured.

### Attempt 0
FLAGS: -O3 -march=native -fopenmp -ffp-contract=fast -funroll-loops
```c
#include <stdlib.h>
#include <string.h>
#include <omp.h>

#if defined(__AVX512F__)
#define VW 16
#else
#define VW 8
#endif

typedef float vf __attribute__((vector_size(VW * 4)));

#define MR 6
#define NR (2 * VW)
#define KC 256
#define MC 120   /* multiple of MR */

static inline void kernel(int kc, const float *restrict Ap, const float *restrict Bp,
                          float *restrict C, int ldc, int first, int mr, int nr)
{
    vf c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    vf c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

    for (int k = 0; k < kc; k++) {
        vf b0 = *(const vf *)(Bp + k * NR);
        vf b1 = *(const vf *)(Bp + k * NR + VW);
        const float *a = Ap + k * MR;
        vf a0 = (vf){0} + a[0];
        c00 += a0 * b0; c01 += a0 * b1;
        vf a1 = (vf){0} + a[1];
        c10 += a1 * b0; c11 += a1 * b1;
        vf a2 = (vf){0} + a[2];
        c20 += a2 * b0; c21 += a2 * b1;
        vf a3 = (vf){0} + a[3];
        c30 += a3 * b0; c31 += a3 * b1;
        vf a4 = (vf){0} + a[4];
        c40 += a4 * b0; c41 += a4 * b1;
        vf a5 = (vf){0} + a[5];
        c50 += a5 * b0; c51 += a5 * b1;
    }

    float tmp[MR * NR] __attribute__((aligned(64)));
    memcpy(tmp + 0 * NR, &c00, sizeof(vf)); memcpy(tmp + 0 * NR + VW, &c01, sizeof(vf));
    memcpy(tmp + 1 * NR, &c10, sizeof(vf)); memcpy(tmp + 1 * NR + VW, &c11, sizeof(vf));
    memcpy(tmp + 2 * NR, &c20, sizeof(vf)); memcpy(tmp + 2 * NR + VW, &c21, sizeof(vf));
    memcpy(tmp + 3 * NR, &c30, sizeof(vf)); memcpy(tmp + 3 * NR + VW, &c31, sizeof(vf));
    memcpy(tmp + 4 * NR, &c40, sizeof(vf)); memcpy(tmp + 4 * NR + VW, &c41, sizeof(vf));
    memcpy(tmp + 5 * NR, &c50, sizeof(vf)); memcpy(tmp + 5 * NR + VW, &c51, sizeof(vf));

    if (mr == MR && nr == NR) {
        for (int r = 0; r < MR; r++) {
            float *cr = C + (size_t)r * ldc;
            vf v0 = *(const vf *)(tmp + r * NR);
            vf v1 = *(const vf *)(tmp + r * NR + VW);
            if (!first) {
                vf o0, o1;
                memcpy(&o0, cr, sizeof(vf));
                memcpy(&o1, cr + VW, sizeof(vf));
                v0 += o0; v1 += o1;
            }
            memcpy(cr, &v0, sizeof(vf));
            memcpy(cr + VW, &v1, sizeof(vf));
        }
    } else {
        for (int r = 0; r < mr; r++) {
            float *cr = C + (size_t)r * ldc;
            if (first)
                for (int j = 0; j < nr; j++) cr[j] = tmp[r * NR + j];
            else
                for (int j = 0; j < nr; j++) cr[j] += tmp[r * NR + j];
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int npan = (n + NR - 1) / NR;
    int nrb = (n + MC - 1) / MC;
    float *Bp = (float *)aligned_alloc(64, (size_t)npan * KC * NR * sizeof(float));

    int nthreads = omp_get_max_threads();
    long work = (long)n * n * n;
    if (work < 64L * 64 * 64) nthreads = 1;

    #pragma omp parallel num_threads(nthreads)
    {
        float *Ap = (float *)aligned_alloc(64, (size_t)MC * KC * sizeof(float));

        for (int kk = 0; kk < n; kk += KC) {
            int kc = n - kk < KC ? n - kk : KC;
            int first = (kk == 0);

            #pragma omp for schedule(static)
            for (int p = 0; p < npan; p++) {
                float *dst = Bp + (size_t)p * KC * NR;
                int j0 = p * NR;
                int nr = n - j0 < NR ? n - j0 : NR;
                for (int k = 0; k < kc; k++) {
                    const float *src = B + (size_t)(kk + k) * n + j0;
                    float *d = dst + k * NR;
                    int j = 0;
                    for (; j < nr; j++) d[j] = src[j];
                    for (; j < NR; j++) d[j] = 0.0f;
                }
            }

            #pragma omp for schedule(dynamic, 1)
            for (int rb = 0; rb < nrb; rb++) {
                int i0 = rb * MC;
                int mc = n - i0 < MC ? n - i0 : MC;
                int nmp = (mc + MR - 1) / MR;

                for (int mp = 0; mp < nmp; mp++) {
                    float *d = Ap + (size_t)mp * KC * MR;
                    int r0 = i0 + mp * MR;
                    int mr = n - r0 < MR ? n - r0 : MR;
                    for (int r = 0; r < MR; r++) {
                        if (r < mr) {
                            const float *src = A + (size_t)(r0 + r) * n + kk;
                            for (int k = 0; k < kc; k++) d[k * MR + r] = src[k];
                        } else {
                            for (int k = 0; k < kc; k++) d[k * MR + r] = 0.0f;
                        }
                    }
                }

                for (int p = 0; p < npan; p++) {
                    int j0 = p * NR;
                    int nr = n - j0 < NR ? n - j0 : NR;
                    const float *bp = Bp + (size_t)p * KC * NR;
                    for (int mp = 0; mp < nmp; mp++) {
                        int r0 = i0 + mp * MR;
                        int mr = n - r0 < MR ? n - r0 : MR;
                        kernel(kc, Ap + (size_t)mp * KC * MR, bp,
                               C + (size_t)r0 * n + j0, n, first, mr, nr);
                    }
                }
            }
        }
        free(Ap);
    }
    free(Bp);
}
```
